// SM809 IAP patcher: turns the vendor updater SM809_Mouse_Wired_USB_IAP25-08-11-1.exe
// into SM809_Mouse_IAP_zones.exe — the same updater with
//
//   - the zones firmware: the side-light fix (d64: one lighting command,
//     sent with a delay) plus switchable lighting zones (see docs/PROTOCOL.md);
//   - English user interface;
//   - forced update (also when the mouse already reports this firmware);
//   - 30 s wait for the mouse to reconnect after the update.
//
// Only our changes are stored here (patch_data.go, generated by mkpatch.py);
// the vendor updater is needed as input and is checked by its SHA-256.
//
// Usage: drag the vendor updater onto this exe, or put both in one folder and
// run it, or: sm809-iap-patch <vendor updater> [output]
package main

import (
	"bufio"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type run struct {
	off  int
	data string // hex
}

const outName = "SM809_Mouse_IAP_zones.exe"

func patch(orig []byte) ([]byte, error) {
	if len(orig) != origSize || sum(orig) != origSHA256 {
		return nil, errors.New("this is not SM809_Mouse_Wired_USB_IAP25-08-11-1.exe (size or SHA-256 differs) / это не SM809_Mouse_Wired_USB_IAP25-08-11-1.exe (размер или SHA-256 не совпадают)")
	}
	out := append([]byte(nil), orig...)
	for _, r := range runs {
		b, err := hex.DecodeString(r.data)
		if err != nil {
			return nil, err
		}
		copy(out[r.off:], b)
	}
	tail, err := base64.StdEncoding.DecodeString(tailB64)
	if err != nil {
		return nil, err
	}
	out = append(out, tail...)
	if len(out) != resultSize || sum(out) != resultSHA256 {
		return nil, errors.New("internal error: result checksum mismatch / внутренняя ошибка: контрольная сумма результата не совпала")
	}
	return out, nil
}

func sum(b []byte) string { s := sha256.Sum256(b); return hex.EncodeToString(s[:]) }

// findInput looks for the vendor updater next to this exe and in the current folder.
func findInput() (string, error) {
	var dirs []string
	if exe, err := os.Executable(); err == nil {
		dirs = append(dirs, filepath.Dir(exe))
	}
	if wd, err := os.Getwd(); err == nil {
		dirs = append(dirs, wd)
	}
	for _, d := range dirs {
		ents, _ := os.ReadDir(d)
		for _, e := range ents {
			if e.IsDir() || !strings.EqualFold(filepath.Ext(e.Name()), ".exe") {
				continue
			}
			if i, err := e.Info(); err != nil || i.Size() != origSize {
				continue
			}
			p := filepath.Join(d, e.Name())
			if b, err := os.ReadFile(p); err == nil && sum(b) == origSHA256 {
				return p, nil
			}
		}
	}
	return "", errors.New("vendor updater not found: drag SM809_Mouse_Wired_USB_IAP25-08-11-1.exe onto this program\n" +
		"фирменный прошивальщик не найден: перетащите SM809_Mouse_Wired_USB_IAP25-08-11-1.exe на эту программу")
}

func main() {
	err := runMain()
	if err != nil {
		fmt.Println()
		fmt.Println("ERROR / ОШИБКА:", err)
	}
	fmt.Println()
	fmt.Print("Press Enter to close / Нажмите Enter, чтобы закрыть…")
	_, _ = bufio.NewReader(os.Stdin).ReadString('\n')
	if err != nil {
		os.Exit(1)
	}
}

func runMain() error {
	fmt.Println("SM809 IAP patcher — lighting zones firmware / прошивка с зонами подсветки")
	fmt.Println()
	in := ""
	if len(os.Args) > 1 {
		in = os.Args[1]
	} else {
		p, err := findInput()
		if err != nil {
			return err
		}
		in = p
	}
	orig, err := os.ReadFile(in)
	if err != nil {
		return err
	}
	res, err := patch(orig)
	if err != nil {
		return err
	}
	out := filepath.Join(filepath.Dir(in), outName)
	if len(os.Args) > 2 {
		out = os.Args[2]
	}
	if err := os.WriteFile(out, res, 0644); err != nil {
		return err
	}
	fmt.Println("Created / Создан:", out)
	fmt.Println(`
Before flashing / Перед прошивкой:
  - close SM809 Control, the vendor software and the web driver;
    закройте SM809 Control, фирменную программу и веб-драйвер;
  - connect the mouse with the cable / подключите мышь кабелем.

After flashing / После прошивки:
  1. The update erases the mouse settings and the dongle pairing (the stock
     updater does it too). Unplug the dongle and plug it back in — it pairs
     with the mouse on its own.
     Прошивка стирает настройки мыши и привязку к донглу (заводской
     прошивальщик тоже). Выньте донгл и вставьте обратно — он сам привяжет мышь.
  2. In SM809 Control: Settings → Mouse → Read settings from the mouse (cable),
     then write your profile.
     В SM809 Control: Настройки → Мышь → Прочитать настройки из мыши (по кабелю),
     затем запишите свой профиль.

To go back, flash the original updater / Чтобы вернуть заводскую прошивку,
прошейте оригинальным прошивальщиком.`)
	return nil
}
